// src/pages/Dashboard.jsx
import React, { useEffect, useState } from 'react';
import api from '../api/landinghub';

const Dashboard = () => {
  const [landings, setLandings] = useState([]);

  useEffect(() => {
    api.get('/user/landings').then(res => setLandings(res.data));
  }, []);

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Navbar */}
      <header className="bg-white shadow p-4 flex justify-between items-center">
        <h1 className="text-2xl font-bold text-blue-600">LandingHub Marketplace</h1>
        <div className="flex items-center gap-4">
          <button className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">Create New</button>
          <span className="font-medium">Hello, User</span>
        </div>
      </header>

      {/* Hero */}
      <section className="text-center py-10">
        <h2 className="text-3xl font-bold mb-2">Your Landing Pages</h2>
        <p className="text-gray-600">Browse, view, or edit your landing pages in one place</p>
      </section>

      {/* Grid Marketplace */}
      <main className="p-4 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
        {landings.map(l => (
          <div key={l.id} className="bg-white rounded-lg shadow hover:shadow-lg transition overflow-hidden">
            <img src={l.thumbnail} alt={l.title} className="w-full h-40 object-cover" />
            <div className="p-4">
              <h3 className="text-lg font-bold mb-2">{l.title}</h3>
              <p className="text-gray-500 mb-4 line-clamp-2">{l.description}</p>
              <button
                className="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700"
                onClick={() => window.location.href = `/editor/${l.id}`}
              >
                Edit
              </button>
            </div>
          </div>
        ))}
      </main>

      {/* Footer */}
      <footer className="bg-white text-center py-4 text-gray-500">
        © 2025 LandingHub Iconic
      </footer>
    </div>
  );
};

export default Dashboard;
